// Auto-load function that runs on page load
function loadDefaultIdeas() {
    // Check if we already have ideas in localStorage
    const existingIdeas = localStorage.getItem('ideaBank_ideas');
    
    if (existingIdeas) {
        const ideas = JSON.parse(existingIdeas);
        if (ideas.length > 0) {
            console.log('Ideas already loaded from localStorage:', ideas.length);
            return false; // Don't load defaults
        }
    }

    console.log('Loading default ideas:', DEFAULT_IDEAS.length);
    
    // Import the default ideas
    if (typeof ideaBank !== 'undefined') {
        DEFAULT_IDEAS.forEach(idea => {
            ideaBank.addIdea({
                ...idea,
                isDefault: true,  // Mark as default insight
                isUserCreated: false
            });
        });
        
        if (typeof ui !== 'undefined') {
            ui.updateStats();
        }
        
        console.log('✅ Loaded 143 default ideas successfully');
        alert('✅ Loaded 143 ideas from doctor_content_bank.xlsx!');
        return false; // Loaded successfully
    }
    
    return true; // ideaBank not ready
}
